import { useState } from "react";
import "./styles/AuthLayout.css";
import "./styles/Register.css";

const SPARKS = Array.from({ length: 8 }, (_, i) => ({
  id: i,
  left: `${8 + i * 9}%`,
  size: i % 3 === 0 ? 4 : i % 3 === 1 ? 2 : 3,
  duration: 8 + (i % 5) * 2,
  delay: i * 1.1,
  color: i % 3 === 0 ? "#ffb347" : i % 3 === 1 ? "#ffd060" : "#ff8c00",
}));

export default function AccommodationLogin({ onSuccess, onBack, onRegister }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState(null);

  function handleSubmit() {
    setError(null);
    const profile = JSON.parse(localStorage.getItem("accommodation_owner_profile") || "null");
    const u = (username || "").trim().toLowerCase();
    const p = (password || "").trim();

    if (profile && (profile.username || "") && (profile.password || "")) {
      if ((profile.username || "").trim().toLowerCase() === u && String(profile.password || "") === p) {
        localStorage.setItem("accommodation_owner_current", JSON.stringify(profile));
        alert("Login successful — opening Accommodation Entry");
        onSuccess && onSuccess();
        return;
      }
    }

    // fallback demo
    if (u === "owner" && p === "lodge123") {
      alert("Login successful — opening Accommodation Entry");
      onSuccess && onSuccess();
      return;
    }

    setError("Invalid credentials. Use registered owner credentials or demo owner / lodge123");
  }

  return (
    <div className="auth-layout">
      <div className="auth-gold-bar" />

      <div className="auth-left">
        <div className="auth-left-bg" />
        <div className="auth-arch" />
        <div className="auth-om-bg">ॐ</div>

        <div className="auth-sparks">
          {SPARKS.map((s) => (
            <div key={s.id} className="auth-spark" style={{ left: s.left, width: s.size, height: s.size, background: s.color, boxShadow: `0 0 ${s.size * 3}px ${s.color}`, animationDuration: `${s.duration}s`, animationDelay: `${s.delay}s` }} />
          ))}
        </div>

        <div className="auth-left-vert">Accommodation · Owner Login · 2026</div>

        <div className="auth-left-content">
          <div className="auth-eyebrow">Hospitality Partner</div>
          <h1 className="auth-left-title">Accommodation<br/><em>Management</em></h1>
          <p className="auth-left-desc">Register and manage your lodge listing, room types and availability for pilgrims.</p>
        </div>
      </div>

      <div className="auth-right">
        <button className="auth-back-btn" onClick={onBack}>← Home</button>

        <div className="auth-mandala" />

        <div className="auth-form-card">
          <div className="auth-heading">Accommodation Owner Login</div>
          <div className="auth-subheading">Manage your lodge listing and rooms</div>

          <div className="auth-tabs">
            <button className="auth-tab" onClick={onBack}>LOGIN</button>
            <button className="auth-tab" onClick={onRegister}>REGISTER</button>
          </div>

          <div className="auth-fields">
            {error && <div className={`auth-alert error`}>{error}</div>}

            <div className="auth-field">
              <div className="auth-field-label">Username</div>
              <div className="auth-field-wrap">
                <span className="auth-field-icon">👤</span>
                <input className="auth-field-input" value={username} onChange={(e) => setUsername(e.target.value)} />
              </div>
            </div>

            <div className="auth-field">
              <div className="auth-field-label">Password</div>
              <div className="auth-field-wrap">
                <span className="auth-field-icon">🔒</span>
                <input className="auth-field-input" type="password" value={password} onChange={(e) => setPassword(e.target.value)} />
              </div>
            </div>

            <button className="auth-btn" onClick={handleSubmit}>
              {"🏨  "}ENTER ACCOMMODATION PORTAL
            </button>

            <div className="auth-switch" style={{ marginTop: 12 }}>
              New Lodge? &nbsp;
              <span onClick={onRegister}>Register now →</span>
            </div>

            <div style={{ marginTop: 12, fontSize: 12, color: "#666" }}>
              Demo: username <strong>owner</strong> / password <strong>lodge123</strong>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}
